            { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "Drain and refill the cooling system with genuine BMW HT-12 coolant.", parts: ["6.5L HT-12 Coolant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
            { interval: "As Needed", timeLimit: "As Needed", task: "AdBlue Refill", details: "Refill the 12.5L SCR tank with ISO 22241 standard AdBlue. Do not overfill to prevent crystalization on the delicate sensors.", parts: ["AdBlue Fluid"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "25 EUR" }
