          { partName: "Diesel Fuel Filter", category: "Fuel", oem: { brand: "BMW Genuine", code: "13328582272", approxPrice: "60 EUR" }, crossRef: { brand: "Mann Filter", code: "WK 5002 x", approxPrice: "25 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=13328582272", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=13328582272" }, note: "CRITICAL: Protects HPFP." },
          { partName: "Haldex Filter Screen Kit", category: "Drivetrain", oem: { brand: "BMW Genuine", code: "N/A", approxPrice: "150 EUR" }, crossRef: { brand: "BorgWarner", code: "2003085", approxPrice: "85 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=2003085", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=2003085" }, note: "Mandatory for xDrive models." }
