        engineeringData: { blockDesign: "Inline-3, Closed-deck Aluminum block. The B38 is part of the modular engine family, inheriting the immense structural strength of the B58 inline-6. The closed-deck design provides a highly rigid cylinder area.", crankshaft: "Forged Steel, supported by 4 main bearings, with a dedicated counter-rotating balance shaft to mitigate the severe 3-cylinder vibrations.", pistonSpeed: "14.2 m/s @ 6000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features an 11.0:1 compression ratio optimized for efficiency.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "12-valve DOHC design. Flow is highly optimized for immediate turbo response. The head integrates the Valvetronic and Double-VANOS systems for infinite variability.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH sides. Driven by the rear timing chain cassette.", lifterType: "Hydraulic bucket tappets.", specialFeature: "TU2 Update & OPF. The Technical Update 2 (TU2) focused heavily on thermal management and emissions compliance. It features a highly restrictive Otto Particulate Filter to meet Euro 6d norms." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "108°C Electronically mapped heat management.", oilCooler: "Integrated heat exchanger on the oil filter housing." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail). Driven by a mechanical HPFP.", injectors: "3x Bosch Solenoid Injectors. Highly robust." }, tuningLimits: { maxSafeTorqueStock: "300 Nm (Limited strictly by the transverse DCT transmission).", maxSafePowerStock: "190 hp (The block is strong, but the small turbo and exhaust OPF are massive bottlenecks).", maxSafeRPM: "6500 RPM", weakestLink: "Engine Mounts, Plastic Expansion Tank, OPF Filter, PCV Valve Diaphragm." }, electrical: { coils: "Individual Coil Pack system (3x Coil-on-Plug).", ecu: "Bosch MG1 (Requires physical FEMTO unlock in Finland)." } },
        recommendedParts: { description: "Crucial maintenance parts to manage the 3-cylinder vibrations and ensure cooling system reliability for the B38 TU2.", parts: [ { category: "Engine Mount (Right Side)", brand: "Lemförder / Corteco", note: "CRITICAL: Replace every 80k km to absorb vibrations." }, { category: "Transmission Mount", brand: "Lemförder", note: "CRITICAL: Replace alongside the main engine mount." }, { category: "Coolant Expansion Tank & Cap", brand: "Genuine BMW / Mahle", note: "CRITICAL: Replaces the weeping plastic tank." }, { category: "Valve Cover Assembly", brand: "Victor Reinz / BMW", note: "CRITICAL: Replaces the integrated torn PCV membrane." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco", note: "Replaces the tearing rubber pulley core." }, { category: "Electric Water Pump", brand: "Pierburg", note: "Replace proactively around 100k km." }, { category: "Spark Plugs", brand: "NGK SILZKGR8C8S", note: "Require specific 12-point socket." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Prevents oil leaks onto the drive belt." } ] },
