            { interval: "100,000 km", timeLimit: "Unlimited", task: "Vibration Damper Inspection", details: "Carefully inspect the heavy rubber core of the crankshaft pulley for microscopic tears.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Replace the primary drive belt and tensioner system.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "90 EUR" }
